#!/bin/sh
# ============================================================================
#  build.sh — rebuild the import/export fixture ../../fixtures/os2-impexp.BIN
#
#  Toolchain: Open Watcom v2 (verified with "Version 2.0 beta Oct 19 2026",
#  Linux host, installed in /opt/watcom). Override with WATCOM=/path/to/watcom.
#
#  Run from anywhere — all paths are resolved relative to this file. The object
#  and the intermediate image go to ./build/, the fixture is copied to
#  ../../fixtures/, and MANIFEST.txt (next to this script) records the toolchain
#  version plus the size and sha256 of the produced file.
#
#  Why this fixture exists: it is the smallest file in the corpus that carries
#  a non-empty **import procedure** table and an entry table with an ordinal
#  gap, so the `[LEN][STRING][ORDINAL DW]` name entry, the mandatory null entry
#  of the procedure table, and the "unused" entry bundle are all pinned by
#  bytes this repository owns. See README.md in this directory.
#
#  Licensing of the result: the compiled image is test data under
#  ../../license-openwatcom; the source is MIT. No extender or DLL is embedded,
#  so license-dos32a / license-dos4gw do not apply to this file.
# ============================================================================
set -eu

WATCOM="${WATCOM:-/opt/watcom}"
export WATCOM
# One assignment per export statement — see sources/dos4gw/build.sh.
export PATH="$WATCOM/binl64:$PATH"
export INCLUDE="$WATCOM/h"
export LIBS="$WATCOM/lib386"

src=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
build="$src/build"
fixtures="$src/../../fixtures"

mkdir -p "$build"
rm -f "$build"/*.obj "$build"/*.exe
cd "$build"

# -bt=os2  : the OS/2 name-decoration convention (a trailing underscore on
#            every C symbol) — the linker directives below must use it.
# -s       : no stack check, so nothing from the C runtime is referenced. The
#            image links against no library at all; the two API references are
#            resolved by the IMPort directive, which is what makes the import
#            procedure table carry *names*.
wcc386 -bt=os2 -zq -s -fo=impexp.obj "$src/impexp.c"

# The directives are load-bearing and spelled with the decorated names:
#   EXPort name.ordinal  — ordinals 1 and 7 leave a gap at 2..6, which the
#                          linker fills with an "unused" bundle;
#   IMPort name module   — no ".ext" suffix: with one, this linker writes the
#                          extension where the procedure name belongs.
# `system os2v2` already establishes the executable format, so a `format`
# directive here would be E3057; `format os2 dll` alone would select the
# 16-bit segmented DLL writer (E2053 on a 32-bit object).
wlink option quiet system os2v2 file impexp.obj name impexp.exe \
      export ImpExpSecond_.1,ImpExpProbe_.7 \
      import DosLoadModule_ DOSCALLS,WinQueryWindowPos_ PMWIN

cp impexp.exe "$fixtures/os2-impexp.BIN"

# --- manifest -------------------------------------------------------------
{
    echo "# Regenerated by build.sh — do not edit by hand."
    echo "# Toolchain: $(wlink /v 2>&1 | sed -n '1p')"
    echo "# Format: <sha256> <bytes> <fixture>"
    p="$fixtures/os2-impexp.BIN"
    printf '%s %s %s\n' "$(sha256sum "$p" | cut -d' ' -f1)" \
        "$(wc -c < "$p")" "os2-impexp.BIN"
} > "$src/MANIFEST.txt"

cat "$src/MANIFEST.txt"
